const JSGlobalObject = jsc.JSGlobalObject;
const JSValue = jsc.JSValue;
const ZigString = jsc.ZigString;
pub const Argon2Params = Argon2Params_;
pub const Algorithm = AlgorithmEnum;
pub const AlgorithmDef = AlgorithmDef_;
pub const HashJobResult = HashJobResult_;
pub const HashJob = HashJob_;
pub const VerifyJobResult = VerifyJobResult_;
pub const VerifyJob = VerifyJob_;
const unknown_password_algorithm_message = "unknown algorithm, expected one of: \"bcrypt\", \"argon2id\", \"argon2d\", \"argon2i\" (default is \"argon2id\")";

pub fn algorithmValueFromJS(globalObject: *jsc.JSGlobalObject, value: jsc.JSValue) bun.JSError!Algorithm_Value {
        if (value.isObject()) {
            if (try value.getTruthy(globalObject, "algorithm")) |algorithm_value| {
                _ = &algorithm_value;
                if ((!algorithm_value.isString())) {
                    return globalObject.throwInvalidArgumentType("hash", "algorithm", "string");
                }
                const algorithm_string = try algorithm_value.getZigString(globalObject);
                const maybe_alg = AlgorithmDef_.label.getWithEql(algorithm_string, jsc.ZigString.eqlComptime);
                if ((maybe_alg == null)) {
                    return globalObject.throwInvalidArgumentType("hash", "algorithm", unknown_password_algorithm_message);
                }
                switch (maybe_alg.?) {
.bcrypt => {
var algorithm = Algorithm_Value{ .bcrypt = 10 };
                _ = &algorithm;
                if (try value.getTruthy(globalObject, "cost")) |rounds_value| {
                    _ = &rounds_value;
                    if ((!rounds_value.isNumber())) {
                        return globalObject.throwInvalidArgumentType("hash", "cost", "number");
                    }
                    const rounds = try rounds_value.coerce(i32, globalObject);
                    if (((rounds < 4) or (rounds > 31))) {
                        return globalObject.throwInvalidArguments("Rounds must be between 4 and 31", .{});
                    }
                    algorithm.bcrypt = @as(u6, @intCast(rounds));
                }
                return algorithm;
},
.argon2id => {
var argon = Argon2Params_{  };
                _ = &argon;
                if (try value.getTruthy(globalObject, "timeCost")) |time_value| {
                    _ = &time_value;
                    if ((!time_value.isNumber())) {
                        return globalObject.throwInvalidArgumentType("hash", "timeCost", "number");
                    }
                    const time_cost = try time_value.coerce(i32, globalObject);
                    if ((time_cost < 1)) {
                        return globalObject.throwInvalidArguments("Time cost must be greater than 0", .{});
                    }
                    argon.time_cost = @as(u32, @intCast(time_cost));
                }
                if (try value.getTruthy(globalObject, "memoryCost")) |memory_value| {
                    _ = &memory_value;
                    if ((!memory_value.isNumber())) {
                        return globalObject.throwInvalidArgumentType("hash", "memoryCost", "number");
                    }
                    const memory_cost = try memory_value.coerce(i32, globalObject);
                    if ((memory_cost < 1)) {
                        return globalObject.throwInvalidArguments("Memory cost must be greater than 0", .{});
                    }
                    argon.memory_cost = @as(u32, @intCast(memory_cost));
                }
                return Algorithm_Value{ .argon2id = argon };
},
.argon2d => {
var argon = Argon2Params_{  };
                _ = &argon;
                if (try value.getTruthy(globalObject, "timeCost")) |time_value| {
                    _ = &time_value;
                    if ((!time_value.isNumber())) {
                        return globalObject.throwInvalidArgumentType("hash", "timeCost", "number");
                    }
                    const time_cost = try time_value.coerce(i32, globalObject);
                    if ((time_cost < 1)) {
                        return globalObject.throwInvalidArguments("Time cost must be greater than 0", .{});
                    }
                    argon.time_cost = @as(u32, @intCast(time_cost));
                }
                if (try value.getTruthy(globalObject, "memoryCost")) |memory_value| {
                    _ = &memory_value;
                    if ((!memory_value.isNumber())) {
                        return globalObject.throwInvalidArgumentType("hash", "memoryCost", "number");
                    }
                    const memory_cost = try memory_value.coerce(i32, globalObject);
                    if ((memory_cost < 1)) {
                        return globalObject.throwInvalidArguments("Memory cost must be greater than 0", .{});
                    }
                    argon.memory_cost = @as(u32, @intCast(memory_cost));
                }
                return Algorithm_Value{ .argon2d = argon };
},
.argon2i => {
var argon = Argon2Params_{  };
                _ = &argon;
                if (try value.getTruthy(globalObject, "timeCost")) |time_value| {
                    _ = &time_value;
                    if ((!time_value.isNumber())) {
                        return globalObject.throwInvalidArgumentType("hash", "timeCost", "number");
                    }
                    const time_cost = try time_value.coerce(i32, globalObject);
                    if ((time_cost < 1)) {
                        return globalObject.throwInvalidArguments("Time cost must be greater than 0", .{});
                    }
                    argon.time_cost = @as(u32, @intCast(time_cost));
                }
                if (try value.getTruthy(globalObject, "memoryCost")) |memory_value| {
                    _ = &memory_value;
                    if ((!memory_value.isNumber())) {
                        return globalObject.throwInvalidArgumentType("hash", "memoryCost", "number");
                    }
                    const memory_cost = try memory_value.coerce(i32, globalObject);
                    if ((memory_cost < 1)) {
                        return globalObject.throwInvalidArguments("Memory cost must be greater than 0", .{});
                    }
                    argon.memory_cost = @as(u32, @intCast(memory_cost));
                }
                return Algorithm_Value{ .argon2i = argon };
},
}
                _ = unreachable;
            } else {
                return globalObject.throwInvalidArgumentType("hash", "options.algorithm", "string");
            }
        } else {
            if (value.isString()) {
                const algorithm_string = try value.getZigString(globalObject);
                const maybe_alg = AlgorithmDef_.label.getWithEql(algorithm_string, jsc.ZigString.eqlComptime);
                if ((maybe_alg == null)) {
                    return globalObject.throwInvalidArgumentType("hash", "algorithm", unknown_password_algorithm_message);
                }
                switch (maybe_alg.?) {
.bcrypt => {
return Algorithm_Value{ .bcrypt = 10 };
},
.argon2id => {
return Algorithm_Value{ .argon2id = .{} };
},
.argon2d => {
return Algorithm_Value{ .argon2d = .{} };
},
.argon2i => {
return Algorithm_Value{ .argon2i = .{} };
},
}
            } else {
                return globalObject.throwInvalidArgumentType("hash", "algorithm", "string");
            }
        }
        _ = unreachable;
}

pub fn formatPasswordErrorCode(err_name: []const u8) []const u8 {
        var out = (blk_catch_5: { break :blk_catch_5 ((bun.default_allocator.alloc(u8, ((err_name.len * 2) + 9))) catch |__ce_5| { _ = &__ce_5; return "PASSWORD_ERROR"; }); });
        _ = &out;
        _ = @memcpy(out[0..8], "PASSWORD");
        var j: usize = 8;
        _ = &j;
        {
            var i: i32 = 0;
            _ = &i;
            const __end_0 = err_name.len;
            while (i < __end_0) : (i += 1) {
                const c = err_name[@as(usize, @intCast(i))];
                if (std.ascii.isUpper(c)) {
                    out[cp_cast_int(usize, j)] = 95;
                    j = (j + 1);
                    out[cp_cast_int(usize, j)] = c;
                    j = (j + 1);
                } else {
                    if (std.ascii.isLower(c)) {
                        out[cp_cast_int(usize, j)] = std.ascii.toUpper(c);
                        j = (j + 1);
                    } else {
                        out[cp_cast_int(usize, j)] = c;
                        j = (j + 1);
                    }
                }
            }
        }
        return out[0..j];
}
